import os,json,subprocess
from pathlib import Path
src=Path("/home/ubuntu/codex-agent");dst=Path("/srv/projects/codex-agent")
out={"project":"codex-agent","status":"BLOCKED","changed":False}
def states():
 names=("ssh","nginx","fadego-staging","lowcost-europa","pink-iptv-backend","pm2-root")
 return {s:subprocess.run(["systemctl","is-active",s],capture_output=True,text=True,timeout=6).stdout.strip() for s in names}
try:
 if not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("preflight_source_or_target")
 if src.stat().st_dev!=dst.parent.stat().st_dev:raise RuntimeError("cross_device_move")
 if not (src/"package.json").is_file() or not (src/"node_modules").is_dir():raise RuntimeError("codex_package_not_recognized")
 for pid in Path("/proc").iterdir():
  if not pid.name.isdigit():continue
  for path in ("cwd","exe"):
   try:
    where=os.readlink(str(pid/path))
    if where==str(src) or where.startswith(str(src)+"/"):raise RuntimeError("codex_agent_live_execution")
   except (OSError,PermissionError):pass
 prev=src.stat();health=states()
 os.rename(src,dst)
 try:
  os.symlink(str(dst),src)
  after=dst.stat()
  if not src.is_symlink() or src.resolve(strict=True)!=dst or dst.is_symlink() or (prev.st_ino,prev.st_dev,prev.st_uid,prev.st_gid)!=(after.st_ino,after.st_dev,after.st_uid,after.st_gid):raise RuntimeError("identity_mismatch")
  if states()!=health:raise RuntimeError("service_changed")
  if not (dst/"package.json").is_file() or not (dst/"node_modules").is_dir():raise RuntimeError("package_missing_after")
  out.update(status="MOVED_VERIFIED",changed=True,root=str(dst),old_path_alias=True,identity_preserved=True,protected_services_unchanged=True)
 except Exception:
  if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
  if dst.exists() and not src.exists():os.rename(dst,src)
  raise
except Exception as err:out["reason"]=str(err)[:180]
print(json.dumps(out,sort_keys=True))
if out["status"]!="MOVED_VERIFIED":raise SystemExit(3)
